                                ["templateID"] = "convo.interaction.scene.grounded_news_share.say.1.guarded",
                                ["textRole"] = "spoken_action",
                                ["translations"] = {
                                    ["EN"] = {
                                        "I have something I can confirm.",
                                        "I have verified intel, but keep it quiet.",
